import React, { useState, useEffect } from 'react';
import './DashboardEntrenador.css';
import GestionJugadores from './GestionJugadores';
import GestionEntrenamientos from './GestionEntrenamientos';
import GestionPartidos from './GestionPartidos';
import ControlPagos from './ControlPagos';
import EscanerQR from './EscanerQR';
import { getEstadisticasEquipo, getCurrentUser } from '../../database/db';

function DashboardEntrenador() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [estadisticas, setEstadisticas] = useState({
    total_jugadores: 0,
    promedio_asistencia: 0,
    total_recaudado: 0,
    total_pendiente: 0
  });
  const [user, setUser] = useState(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = async () => {
    setLoading(true);
    try {
      // Obtener usuario actual (síncrono porque viene de localStorage)
      const currentUser = getCurrentUser();
      setUser(currentUser);
      
      // Obtener estadísticas (asíncrono)
      const stats = await getEstadisticasEquipo();
      console.log('Estadísticas recibidas:', stats);
      
      // Mapear los nombres de campos (PostgreSQL devuelve snake_case)
      setEstadisticas({
        total_jugadores: stats.total_jugadores || stats.totalJugadores || 0,
        promedio_asistencia: stats.promedio_asistencia || stats.promedioAsistencia || 0,
        total_recaudado: stats.total_recaudado || stats.totalRecaudado || 0,
        total_pendiente: stats.total_pendiente || stats.totalPendiente || 0
      });
    } catch (error) {
      console.error('Error cargando datos:', error);
    }
    setLoading(false);
  };

  const tabs = [
    { id: 'dashboard', nombre: 'Dashboard', icono: 'fa-chart-line', mobileNombre: '📊' },
    { id: 'jugadores', nombre: 'Jugadores', icono: 'fa-users', mobileNombre: '👥' },
    { id: 'entrenamientos', nombre: 'Entrenamientos', icono: 'fa-futbol', mobileNombre: '⚽' },
    { id: 'partidos', nombre: 'Partidos', icono: 'fa-trophy', mobileNombre: '🏆' },
    { id: 'pagos', nombre: 'Pagos', icono: 'fa-dollar-sign', mobileNombre: '💰' },
    { id: 'escaner', nombre: 'Escáner QR', icono: 'fa-qrcode', mobileNombre: '📷' }
  ];

  const renderContent = () => {
    if (loading && activeTab === 'dashboard') {
      return (
        <div className="loading-container">
          <i className="fas fa-spinner fa-spin"></i>
          <p>Cargando estadísticas...</p>
        </div>
      );
    }

    switch(activeTab) {
      case 'dashboard':
        return (
          <div className="dashboard-stats">
            <div className="stat-card">
              <div className="stat-icon"><i className="fas fa-users"></i></div>
              <div className="stat-info">
                <h3>{estadisticas.total_jugadores || 0}</h3>
                <p>Jugadores</p>
              </div>
            </div>
            <div className="stat-card">
              <div className="stat-icon"><i className="fas fa-chart-line"></i></div>
              <div className="stat-info">
                <h3>{(estadisticas.promedio_asistencia || 0).toFixed(1)}%</h3>
                <p>Asistencia</p>
              </div>
            </div>
            <div className="stat-card">
              <div className="stat-icon"><i className="fas fa-dollar-sign"></i></div>
              <div className="stat-info">
                <h3>${(estadisticas.total_recaudado || 0).toLocaleString()}</h3>
                <p>Recaudado</p>
              </div>
            </div>
            <div className="stat-card">
              <div className="stat-icon"><i className="fas fa-clock"></i></div>
              <div className="stat-info">
                <h3>${(estadisticas.total_pendiente || 0).toLocaleString()}</h3>
                <p>Pendiente</p>
              </div>
            </div>
          </div>
        );
      case 'jugadores':
        return <GestionJugadores />;
      case 'entrenamientos':
        return <GestionEntrenamientos />;
      case 'partidos':
        return <GestionPartidos />;
      case 'pagos':
        return <ControlPagos />;
      case 'escaner':
        return <EscanerQR />;
      default:
        return null;
    }
  };

  return (
    <div className="dashboard-entrenador">
      {/* Header mobile */}
      <div className="mobile-header">
        <div className="mobile-logo">
          <i className="fas fa-whistle"></i>
          <span>FútbolPro</span>
        </div>
        <button className="menu-toggle" onClick={() => setMenuOpen(!menuOpen)}>
          <i className={`fas ${menuOpen ? 'fa-times' : 'fa-bars'}`}></i>
        </button>
      </div>

      {/* Navegación */}
      <nav className={`entrenador-nav ${menuOpen ? 'open' : ''}`}>
        <div className="nav-header">
          <i className="fas fa-whistle"></i>
          <div className="nav-user">
            <span className="user-name">{user?.nombre || 'Entrenador'}</span>
            <span className="user-role">Entrenador</span>
          </div>
        </div>
        <div className="nav-tabs">
          {tabs.map(tab => (
            <button
              key={tab.id}
              className={`nav-tab ${activeTab === tab.id ? 'active' : ''}`}
              onClick={() => { setActiveTab(tab.id); setMenuOpen(false); }}
            >
              <i className={`fas ${tab.icono}`}></i>
              <span className="tab-text">{tab.nombre}</span>
              <span className="tab-icon-mobile">{tab.mobileNombre}</span>
            </button>
          ))}
        </div>
      </nav>

      <div className="dashboard-content">
        {renderContent()}
      </div>
    </div>
  );
}

export default DashboardEntrenador;
